        { t: 'Сундук', text: 'Запас карман не тянет.' },
        { t: 'Роскошный сундук', text: 'Первоклассные припасы.' },
        { t: 'Головоломка решена', text: 'Какой тонкий расчёт.' },
        { t: 'Головоломка решена', text: 'Отлично.' },
        { t: 'Враг замечен', text: 'Обстановка на поле боя изменилась.' },
        { t: 'Возвращение в город', text: 'Если спешить некуда, давай прогуляемся.' }
