        { t: 'Сундук', text: 'Угу, неплохо.' },
        { t: 'Роскошный сундук', text: 'Ха! Как щедро.' },
        { t: 'Головоломка решена', text: 'Очень неплохо.' },
        { t: 'Головоломка решена', text: 'Неужели обязательно было так сложно...' },
        { t: 'Враг замечен', text: 'Впереди враги. Бить или бежать?' },
        { t: 'Возвращение в город', text: 'Давай по очереди. Ты отдыхаешь, я стою на страже.' }
